def _build(params, N):
    p, q, a, b, c = params
    p = min(max(p, 0.02), 1.5)
    q = min(max(q, 0.02), 1.5)
    i = np.arange(N, dtype=float)
    u = (i + 0.5) / N
    h = a * u ** (-p) + b * (1.0 - u) ** (-q) + c
    h = np.clip(h, 0.0, 1e6)
    return h


def _negR(params, N):
    h = _build(params, N)
    if h.sum() <= 0:
        return 1.0
    return -_R(h)


