import time
import numpy as np
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    # small inputs: direct; large: FFT. Avoids O(n^2) at N=20000+.
    if len(a) * len(b) < 200000:
        return np.convolve(a, b)
    return fftconvolve(a, b)


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _conv(h, h)
    num = (np.dot(L, L) + np.dot(L[:-1], L[1:])) / 3.0
    den = s * s * L.max()
    return num / den if den > 0 else 0.0


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    n = len(h)
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    L = _conv(h, h)
    m = len(L)
    num = (np.dot(L, L) + np.dot(L[:-1], L[1:])) / 3.0
    imax = int(np.argmax(L))
    M = L[imax]
    den = s * s * M
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    g = (2.0 / 3.0) * L
    g[:-1] += (1.0 / 3.0) * L[1:]
    g[1:] += (1.0 / 3.0) * L[:-1]
    dR_dL = g / den
    dR_dL[imax] -= (num / den) / M
    corr = _conv(dR_dL, h[::-1])
    grad_h = 2.0 * corr[n - 1: n - 1 + n]
    grad_h -= (2.0 * R / s)
    return R, grad_h


def _negR_grad(y):
    h = np.exp(np.clip(y, -50.0, 50.0))
    R, gh = _R_grad(h)
    return -R, -gh * h


def _resample(h, N):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _opt(y0, maxiter=4000, maxcor=50):
    best_y = y0.copy()
    best_v = -_R(np.exp(np.clip(best_y, -50.0, 50.0)))
    try:
        res = minimize(_negR_grad, best_y, jac=True, method="L-BFGS-B",
                       options={"maxiter": maxiter, "ftol": 1e-17,
                                "gtol": 1e-15, "maxcor": maxcor, "maxls": 80})
        if res.fun < best_v:
            best_v = res.fun
            best_y = np.array(res.x)
    except Exception:
        pass
    return best_y, best_v


def _polish(h, N, until, maxcor=50):
    hh = np.maximum(_resample(np.maximum(h, 0.0), N), 0.0)
    if hh.max() <= 0:
        return h, _R(h)
    hh /= hh.max()
    y = np.log(hh + 1e-10)
    best_h = np.exp(np.clip(y, -50.0, 50.0))
    best_R = _R(best_h)
    while time.process_time() < until:
        y, _v = _opt(y, maxcor=maxcor)
        hb = np.exp(np.clip(y, -50.0, 50.0))
        Rb = _R(hb)
        if Rb > best_R:
            best_R, best_h = Rb, hb
        else:
            break
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        hs = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if hs.sum() <= 0:
            hs = np.ones(400)
    else:
        hs = np.ones(400)

    best_h = hs.copy()
    best_R = _R(hs)

    # First polish at native/moderate resolution to lock in gains from start.
    N0 = max(len(hs), 2000)
    hN, RN = _polish(best_h, N0, deadline, maxcor=50)
    if RN > best_R:
        best_R, best_h = RN, hN

    # Then progressively refine: high resolution, several rounds with
    # increasing memory, alternating to escape local flat regions.
    Ns = [8000, 20000, 40000]
    for N in Ns:
        if time.process_time() >= deadline:
            break
        hN, RN = _polish(best_h, N, deadline, maxcor=100)
        if RN > best_R:
            best_R, best_h = RN, hN

    # Final squeeze: keep polishing the best at the best resolution reached.
    while time.process_time() < deadline:
        improved = False
        for N in Ns:
            if time.process_time() >= deadline:
                break
            hN, RN = _polish(best_h, N, deadline, maxcor=100)
            if RN > best_R + 1e-12:
                best_R, best_h = RN, hN
                improved = True
        if not improved:
            break

    if start is not None:
        hs2 = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if hs2.sum() > 0 and _R(hs2) > best_R:
            best_h, best_R = hs2, _R(hs2)

    print("final R:", best_R, "N:", len(best_h))
    return np.asarray(best_h, dtype=float)

import time
import numpy as np
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = fftconvolve(h, h)
    num = (np.dot(L, L) + np.dot(L[:-1], L[1:])) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    n = len(h)
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    L = fftconvolve(h, h)
    num = (np.dot(L, L) + np.dot(L[:-1], L[1:])) / 3.0
    imax = int(np.argmax(L))
    M = L[imax]
    den = s * s * M
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den

    g = (2.0 / 3.0) * L
    g[:-1] += (1.0 / 3.0) * L[1:]
    g[1:] += (1.0 / 3.0) * L[:-1]

    dR_dL = g / den
    dR_dL[imax] -= (num / den) / M

    corr = fftconvolve(dR_dL, h[::-1])
    grad_h = 2.0 * corr[n - 1: n - 1 + n]
    grad_h -= (2.0 * R / s)
    return R, grad_h


def _negR_grad(y):
    h = np.exp(y)
    R, gh = _R_grad(h)
    return -R, -gh * h


def _resample(h, N):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _block_downsample(h, N):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N:
        return h.copy()
    if n % N != 0:
        return _resample(h, N)
    k = n // N
    return h.reshape(N, k).mean(axis=1)


def _to20(h, N20=20000):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N20:
        return h.copy()
    if n >= N20 and n % N20 == 0:
        return _block_downsample(h, N20)
    return _resample(h, N20)


def _optimize(y0, deadline, maxiter=5000):
    best_y = y0.copy()
    best_v = -_R(np.exp(best_y))
    if time.process_time() > deadline:
        return best_y, best_v
    try:
        res = minimize(_negR_grad, best_y, jac=True, method="L-BFGS-B",
                       options={"maxiter": maxiter, "ftol": 1e-16,
                                "gtol": 1e-14, "maxcor": 50, "maxls": 50})
        if res.fun < best_v:
            best_v = res.fun
            best_y = np.array(res.x)
    except Exception:
        pass
    return best_y, best_v


def _smooth(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    hp = np.concatenate([h[:1].repeat(k // 2), h, h[-1:].repeat(k // 2 + 1)])
    return np.convolve(hp, ker, mode="same")[k // 2: k // 2 + len(h)]


def _upsample_preserve(h, N):
    return np.maximum(_resample(np.maximum(h, 0.0), N), 0.0)


def _refine_multiscale(best_h, best_R, deadline, rng, scales=None):
    if scales is None:
        scales = [3, 5, 9, 17, 33, 65, 129, 257, 513]
    h = np.maximum(best_h, 0.0)
    if h.max() > 0:
        h /= h.max()
    y = np.log(h + 1e-8)
    si = 0
    while time.process_time() < deadline:
        k = scales[si % len(scales)]
        si += 1
        hs = _smooth(np.exp(y), k)
        if hs.max() > 0:
            hs /= hs.max()
        ys = np.log(hs + 1e-8)
        ys, _ = _optimize(ys, deadline, maxiter=1500)
        hr = np.exp(ys)
        Rr = _R(hr)
        if Rr > best_R:
            best_R = Rr
            best_h = hr.copy()
            y = ys
        else:
            y = y + 0.005 * rng.standard_normal(len(y))
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    dA = t0 + budget_seconds * 0.30
    dC = t0 + budget_seconds * 0.85
    dD = deadline

    N20 = 20000
    Nmid = 40000

    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.sum() <= 0:
            hs = np.ones(400)
    else:
        hs = ((np.arange(N20) + 0.5) / N20) ** (-0.5)

    best_h20 = _to20(np.maximum(hs, 0.0), N20)
    best_h20 = np.maximum(best_h20, 0.0)
    best_R20 = _R(best_h20)
    print("initial R: %.12f" % best_R20)
    n_accept = 0

    def consider(hb, tag):
        nonlocal best_h20, best_R20, n_accept
        hb = np.maximum(np.asarray(hb, dtype=float).ravel(), 0.0)
        hb20 = _to20(hb, N20)
        R20 = _R(hb20)
        if R20 > best_R20:
            best_R20 = R20
            best_h20 = hb20.copy()
            n_accept += 1
            print("accept %-10s n=%6d R20=%.12f" % (tag, len(hb), R20))
        return R20

    rng = np.random.default_rng(20240101)

    # Step 1: multiscale + upsample/downsample passes until dC (p0089 path).
    if time.process_time() < dC:
        # quick direct polish at N20 first
        h0 = np.maximum(best_h20, 0.0)
        if h0.max() > 0:
            h0 /= h0.max()
        y = np.log(h0 + 1e-8)
        y, _ = _optimize(y, min(dA, dC), maxiter=4000)
        consider(np.exp(y), "direct-opt")

        while time.process_time() < dC:
            h_up = _upsample_preserve(best_h20, 80000)
            if h_up.max() > 0:
