import time
import numpy as np
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = fftconvolve(h, h)
    num = (np.dot(L, L) + np.dot(L[:-1], L[1:])) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    n = len(h)
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    L = fftconvolve(h, h)
    num = (np.dot(L, L) + np.dot(L[:-1], L[1:])) / 3.0
    imax = int(np.argmax(L))
    M = L[imax]
    den = s * s * M
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den

    g = (2.0 / 3.0) * L
    g[:-1] += (1.0 / 3.0) * L[1:]
    g[1:] += (1.0 / 3.0) * L[:-1]

    dR_dL = g / den
    dR_dL[imax] -= (num / den) / M

    corr = fftconvolve(dR_dL, h[::-1])
    grad_h = 2.0 * corr[n - 1: n - 1 + n]
    grad_h -= (2.0 * R / s)
    return R, grad_h


def _negR_grad(y):
    h = np.exp(y)
    R, gh = _R_grad(h)
    return -R, -gh * h


def _resample(h, N):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _block_downsample(h, N):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N:
        return h.copy()
    if n % N != 0:
        return _resample(h, N)
    k = n // N
    return h.reshape(N, k).mean(axis=1)


def _to20(h, N20=20000):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N20:
        return h.copy()
    if n >= N20 and n % N20 == 0:
        return _block_downsample(h, N20)
    return _resample(h, N20)


def _optimize(y0, deadline, maxiter=5000):
    best_y = y0.copy()
    best_v = -_R(np.exp(best_y))
    if time.process_time() > deadline:
        return best_y, best_v
    try:
        res = minimize(_negR_grad, best_y, jac=True, method="L-BFGS-B",
                       options={"maxiter": maxiter, "ftol": 1e-16,
                                "gtol": 1e-14, "maxcor": 50, "maxls": 50})
        if res.fun < best_v:
            best_v = res.fun
            best_y = np.array(res.x)
    except Exception:
        pass
    return best_y, best_v


def _smooth(h, k):
    if k <= 1:
        return h.copy()
    ker = np.ones(k) / k
    hp = np.concatenate([h[:1].repeat(k // 2), h, h[-1:].repeat(k // 2 + 1)])
    return np.convolve(hp, ker, mode="same")[k // 2: k // 2 + len(h)]


def _upsample_preserve(h, N):
    return np.maximum(_resample(np.maximum(h, 0.0), N), 0.0)


def _refine_multiscale(best_h, best_R, deadline, rng, scales=None):
    if scales is None:
        scales = [3, 5, 9, 17, 33, 65, 129, 257, 513]
    h = np.maximum(best_h, 0.0)
    if h.max() > 0:
        h /= h.max()
    y = np.log(h + 1e-8)
    si = 0
    while time.process_time() < deadline:
        k = scales[si % len(scales)]
        si += 1
        hs = _smooth(np.exp(y), k)
        if hs.max() > 0:
            hs /= hs.max()
        ys = np.log(hs + 1e-8)
        ys, _ = _optimize(ys, deadline, maxiter=1500)
        hr = np.exp(ys)
        Rr = _R(hr)
        if Rr > best_R:
            best_R = Rr
            best_h = hr.copy()
            y = ys
        else:
            y = y + 0.005 * rng.standard_normal(len(y))
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    dA = t0 + budget_seconds * 0.40
    dC = t0 + budget_seconds * 0.88
    dD = deadline

    N20 = 20000
    Nmid = 40000

    # Singular profile seed.
    u = (np.arange(N20) + 0.5) / N20
    h_sing = u ** (-0.5)
    best_h20 = h_sing.copy()
    best_R20 = _R(best_h20)
    print("initial singular R: %.12f" % best_R20)
    n_accept = 0

    # --- Experiment: smooth multiplicative modulation exp(a*u + b*u^2) ---
    def mod_profile(a, b):
        return u ** (-0.5) * np.exp(a * u + b * u * u)

    a_grid = [-0.5, -0.25, 0.0, 0.25, 0.5]
    b_grid = [-0.5, 0.0, 0.5]
    best_ab = (0.0, 0.0)
    best_mod_R = best_R20
    for a in a_grid:
        for b in b_grid:
            Rv = _R(mod_profile(a, b))
            if Rv > best_mod_R:
                best_mod_R = Rv
                best_ab = (a, b)
    print("grid best (a,b)=(%.3f,%.3f) R=%.12f" % (best_ab[0], best_ab[1], best_mod_R))

    # Nelder-Mead refine on -R over (a,b), ~200 evals.
    nm_deadline = min(t0 + budget_seconds * 0.15, dA)

    def negR_ab(x):
        if time.process_time() > nm_deadline:
            raise TimeoutError
        return -_R(mod_profile(x[0], x[1]))

    try:
        res = minimize(negR_ab, np.array(best_ab, dtype=float),
                       method="Nelder-Mead",
                       options={"maxfev": 200, "xatol": 1e-4, "fatol": 1e-10})
        a_r, b_r = float(res.x[0]), float(res.x[1])
        R_r = _R(mod_profile(a_r, b_r))
        if R_r > best_mod_R:
            best_mod_R = R_r
            best_ab = (a_r, b_r)
    except Exception:
        pass
    print("refined (a,b)=(%.5f,%.5f) R=%.12f" % (best_ab[0], best_ab[1], best_mod_R))

    if best_mod_R > best_R20:
        best_R20 = best_mod_R
        best_h20 = mod_profile(*best_ab)
        print("modulation improves seed: R=%.12f" % best_R20)

    def consider(hb, tag):
        nonlocal best_h20, best_R20, n_accept
        hb = np.maximum(np.asarray(hb, dtype=float).ravel(), 0.0)
        hb20 = _to20(hb, N20)
        R20 = _R(hb20)
        if R20 > best_R20:
            best_R20 = R20
            best_h20 = hb20.copy()
            n_accept += 1
            print("accept %-10s n=%6d R20=%.12f" % (tag, len(hb), R20))
        return R20

    rng = np.random.default_rng(20240101)

    # Step 1: direct N=20000 log-space L-BFGS from best seed until dA.
    if time.process_time() < dA:
        h0 = np.maximum(best_h20, 0.0)
        if h0.max() > 0:
            h0 /= h0.max()
        y = np.log(h0 + 1e-8)
        y, _ = _optimize(y, dA, maxiter=8000)
        hb = np.exp(y)
        consider(hb, "sing-opt")
        bm, _ = _refine_multiscale(np.exp(y), _R(np.exp(y)), dA, rng)
        consider(bm, "sing-ms")

    # Step 2: up/down passes until dC.
    if time.process_time() < dC:
        while time.process_time() < dC:
            h_up = _upsample_preserve(best_h20, 80000)
            if h_up.max() > 0:
                h_up /= h_up.max()
            y = np.log(h_up + 1e-8)
            y, _ = _optimize(y, dC, maxiter=3000)
            hb = np.exp(y)
            consider(hb, "up-pass")
            h_mid = _block_downsample(hb, Nmid)
            if h_mid.max() > 0:
                h_mid /= h_mid.max()
            y = np.log(h_mid + 1e-8)
            y, _ = _optimize(y, dC, maxiter=3000)
            hb2 = np.exp(y)
            consider(hb2, "mid-pass")
            if time.process_time() >= dC:
                break
            bm, _ = _refine_multiscale(best_h20, best_R20, dC, rng)
            consider(bm, "ms-20k")

    # Step 3: final tight N=20000 polish until dD.
    if time.process_time() < dD:
        h_fin = np.maximum(best_h20, 0.0)
        if h_fin.max() > 0:
            h_fin /= h_fin.max()
        y = np.log(h_fin + 1e-8)
        while time.process_time() < dD:
            y, v = _optimize(y, dD, maxiter=5000)
            hb = np.exp(y)
            Rb = _R(hb)
            if Rb > best_R20:
                best_R20 = Rb
                best_h20 = hb.copy()
                n_accept += 1
                print("accept %-10s n=%6d R20=%.12f" % ("final-opt", len(hb), Rb))
            else:
                y = y + 0.001 * rng.standard_normal(len(y))

    print("final R:", best_R20, "N:", len(best_h20), "accepts:", n_accept)
    return np.asarray(best_h20, dtype=float)

