    # exact-ish cell averages of x^-p with optional offset alpha
    i = np.arange(N, dtype=float)
    if p >= 1.0 and alpha == 0.0:
        return None
    x = (i + alpha) / N
    h = np.empty(N)
    if alpha == 0.0:
        # first cell average of x^-p over [0,1/N]
        if p == 1.0:
            h[0] = N * 1.0  # integral of 1/x over [1/N,1] ~ N*log N; use large
        else:
            h[0] = (N ** p) / (1.0 - p)
        h[1:] = x[1:] ** (-p)
    else:
        h[:] = x ** (-p)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    dA = t0 + budget_seconds * 0.40
    dC = t0 + budget_seconds * 0.88
    dD = deadline

    N20 = 20000
    Nmid = 40000

