    ps = [0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.7]
    alphas = [0.0, 0.5, 1.0]
    best_h20 = None
    best_R20 = -1.0
    for p in ps:
        for alpha in alphas:
            if alpha == 0.0 and p >= 1.0:
                continue
            h = _power_seed(N20, p, alpha)
            if h is None:
                continue
            R = _R(h)
            print("scan p=%.2f alpha=%.1f R=%.12f" % (p, alpha, R))
            if R > best_R20:
                best_R20 = R
                best_h20 = h.copy()

