    if start is not None:
        try:
            hs = _to20(np.maximum(np.asarray(start, dtype=float).ravel(), 0.0), N20)
            Rs = _R(hs)
            print("start R: %.12f" % Rs)
            if Rs > best_R20:
                best_R20 = Rs
