        hb = np.exp(y)
        consider(hb, "seed-opt")
        bm, _ = _refine_multiscale(np.exp(y), _R(np.exp(y)), dA, rng)
        consider(bm, "seed-ms")

    # Step 2: multiscale/upsample/block-mean up/down passes until dC.
    if time.process_time() < dC:
