            y_try, _ = _optimize(y_try, dD, maxiter=3000)
            hb = np.exp(y_try)
            Rb = _R(hb)
            if Rb > best_R20:
                best_R20 = Rb
                best_h20 = hb.copy()
                y = y_try
                n_accept += 1
                sigma = max(sigma * 0.7, 0.0005)
            else:
                sigma = min(sigma * 1.1, 0.02)

    print("final R:", best_R20, "N:", len(best_h20), "accepts:", n_accept)
    return np.asarray(best_h20, dtype=float)

