        except Exception:
            pass

    print("seed winner R: %.12f" % best_R20)
    n_accept = 0

    def consider(hb, tag):
        nonlocal best_h20, best_R20, n_accept
        hb = np.maximum(np.asarray(hb, dtype=float).ravel(), 0.0)
        hb20 = _to20(hb, N20)
        R20 = _R(hb20)
        if R20 > best_R20:
            best_R20 = R20
            best_h20 = hb20.copy()
            n_accept += 1
            print("accept %-10s n=%6d R20=%.12f" % (tag, len(hb), R20))
        return R20

    rng = np.random.default_rng(20240101)

    # Step 1: direct N=20000 log-space L-BFGS from the seed until dA.
    if time.process_time() < dA:
        h0 = np.maximum(best_h20, 0.0)
        if h0.max() > 0:
            h0 /= h0.max()
        y = np.log(h0 + 1e-8)
        y, _ = _optimize(y, dA, maxiter=8000)
        consider(np.exp(y), "seed-opt")
        bm, _ = _refine_multiscale(np.exp(y), _R(np.exp(y)), dA, rng)
        consider(bm, "seed-ms")

    # Step 2: up/down passes until dC.
    if time.process_time() < dC:
        while time.process_time() < dC:
            h_up = _upsample_preserve(best_h20, 80000)
            if h_up.max() > 0:
                h_up /= h_up.max()
            y = np.log(h_up + 1e-8)
            y, _ = _optimize(y, dC, maxiter=3000)
            hb = np.exp(y)
            consider(hb, "up-pass")
            h_mid = _block_downsample(hb, Nmid)
            if h_mid.max() > 0:
                h_mid /= h_mid.max()
            y = np.log(h_mid + 1e-8)
            y, _ = _optimize(y, dC, maxiter=3000)
            consider(np.exp(y), "mid-pass")
            if time.process_time() >= dC:
                break
            bm, _ = _refine_multiscale(best_h20, best_R20, dC, rng)
            consider(bm, "ms-20k")

    # Step 3: final tight N=20000 polish until dD.
    if time.process_time() < dD:
        h_fin = np.maximum(best_h20, 0.0)
        if h_fin.max() > 0:
            h_fin /= h_fin.max()
        y = np.log(h_fin + 1e-8)
        while time.process_time() < dD:
            y, v = _optimize(y, dD, maxiter=5000)
            hb = np.exp(y)
            Rb = _R(hb)
            if Rb > best_R20:
                best_R20 = Rb
                best_h20 = hb.copy()
                n_accept += 1
                print("accept %-10s n=%6d R20=%.12f" % ("final-opt", len(hb), Rb))
            else:
                y = y + 0.001 * rng.standard_normal(len(y))

    print("final R:", best_R20, "N:", len(best_h20), "accepts:", n_accept)
    return np.asarray(best_h20, dtype=float)
